<?php

declare(strict_types=1);

namespace GoSuccess\Enhance\Resource;

use GoSuccess\Enhance\Base\AbstractResource;
use GoSuccess\Enhance\DTO\DomainSslCertWithData;
use GoSuccess\Enhance\DTO\NewSslCert;
use GoSuccess\Enhance\DTO\SslCert;
use GoSuccess\Enhance\Enum\HttpMethod;

/**
 * Operations for the "ssl" section of the Enhance API.
 */
final class SslResource extends AbstractResource
{
    /**
     * Returns the SSL for this website domain
     *
     * Endpoint for retrieving SSL certificates for a given website including certificates generated by letsencrypt
     *
     * @link https://apidocs.enhance.com/#/ssl/getWebsiteDomainSslCert
     * GET /v2/domains/{domain_id}/ssl
     *
     * @param string $domainId The id of the domain.
     * @throws \GoSuccess\Enhance\Exception\ApiException
     * @return DomainSslCertWithData|null
     */
    public function getWebsiteDomainSslCert(string $domainId): ?DomainSslCertWithData
    {
        $response = $this->client->request(HttpMethod::GET, "/v2/domains/{$domainId}/ssl");

        return $response->decoded !== null ? DomainSslCertWithData::fromArray($response->decoded) : null;
    }

    /**
     * Upload custom ssl certificate, key and optional fullchain for a given website
     *
     * Endpoint for uploading custom SSL certificate for a given website. Verifies the cert key and maps to relevant domains that the certificate can be applied to. Returns error if no domain match is found.
     * Session holder must be at least a `SuperAdmin` in this org or a parent org, or be a member in this org that has access to the website.
     *
     * @link https://apidocs.enhance.com/#/ssl/uploadWebsiteDomainSslCert
     * POST /v2/domains/{domain_id}/ssl
     *
     * @param string $domainId The id of the domain.
     * @param SslCert $sslCert Cert, private key and optional fullchain.
     * @throws \GoSuccess\Enhance\Exception\ApiException
     * @return NewSslCert|null
     */
    public function uploadWebsiteDomainSslCert(string $domainId, SslCert $sslCert): ?NewSslCert
    {
        $response = $this->client->request(HttpMethod::POST, "/v2/domains/{$domainId}/ssl", [], $sslCert);

        return $response->decoded !== null ? NewSslCert::fromArray($response->decoded) : null;
    }

    /**
     * Returns the SSL for this website domain with the mail.prefix
     *
     * Endpoint for retrieving SSL certificates for a given website including certificates generated by letsencrypt
     *
     * @link https://apidocs.enhance.com/#/ssl/getWebsiteMailDomainSslCert
     * GET /v2/domains/{domain_id}/mail_ssl
     *
     * @param string $domainId The id of the domain.
     * @throws \GoSuccess\Enhance\Exception\ApiException
     * @return DomainSslCertWithData|null
     */
    public function getWebsiteMailDomainSslCert(string $domainId): ?DomainSslCertWithData
    {
        $response = $this->client->request(HttpMethod::GET, "/v2/domains/{$domainId}/mail_ssl");

        return $response->decoded !== null ? DomainSslCertWithData::fromArray($response->decoded) : null;
    }

    /**
     * Upload SSL for mail.customerdomain.
     *
     * @link https://apidocs.enhance.com/#/ssl/uploadWebsiteMailDomainSslCert
     * POST /v2/domains/{domain_id}/mail_ssl
     *
     * @param string $domainId The id of the domain.
     * @param SslCert $sslCert Cert, private key and optional fullchain.
     * @throws \GoSuccess\Enhance\Exception\ApiException
     * @return NewSslCert|null
     */
    public function uploadWebsiteMailDomainSslCert(string $domainId, SslCert $sslCert): ?NewSslCert
    {
        $response = $this->client->request(HttpMethod::POST, "/v2/domains/{$domainId}/mail_ssl", [], $sslCert);

        return $response->decoded !== null ? NewSslCert::fromArray($response->decoded) : null;
    }

    /**
     * Set "force ssl" status for domain mapping
     *
     * @link https://apidocs.enhance.com/#/ssl/setWebsiteDomainForceSsl
     * PUT /v2/domains/{domain_id}/ssl/force_ssl
     *
     * @param string $domainId The id of the domain.
     * @param bool $value Boolean "force ssl" setting
     * @throws \GoSuccess\Enhance\Exception\ApiException
     * @return bool True on success
     */
    public function setWebsiteDomainForceSsl(string $domainId, ?bool $value): bool
    {
        $response = $this->client->request(HttpMethod::PUT, "/v2/domains/{$domainId}/ssl/force_ssl", [], $value);

        return $response->isSuccess;
    }
}
